import type { Story } from "./stories";

export const stories800: Record<number, Story> = {
	800: {
		index: 800,
		text: `<p>Your victim flees, protesting and begging you not to hurt him. You withdraw before others are drawn to his cries. [Stealth and Stealing]</p>`,
	},
	801: {
		index: 801,
		text: `<p>Your attack takes the other by surprise, but his strenuous acts of devotion and purity of faith have made him strong and determined. He defends himself very effectively.</p>
<p><b>No Skill:</b> You realize his strength too late and cannot disengage. He batters you unconscious and walks away in contempt. [D1/<em>Wounded</em>]</p>
<p><b>Quick Thinking:</b> You have a sudden idea and you begin to whirl in place and chant clumsily. The dervish is taken in by your pretense and is fooled into thinking that what he thought was an attack was actually a peculiar and vigorous devotional ritual. Politely (but warily), he permits you to go on your way. [D1/Wisdom]</p>`,
	},
	802: {
		index: 802,
		text: `<p>The soldier agrees to work for you. In the passing days, you notice him staring at you with great malice in his gaze.</p>
<p><b>No Skill:</b> One morning soon after, you awaken to find yourself gagged and bound. "Now I shall have vengeance for what you did to my parents," he leers. Were you not gagged, you could tell him of his error, but he beats and robs you and leaves you to die. You free yourself with difficulty, and cannot find him to seek justice. [D1/W-2 (Min: Penniless)/<em>Wounded</em>]</p>
<p><b>Storytelling:</b> One night you share your life story with him. When you are finished, he looks greatly puzzled and says, "You are not who I thought you were." He gives back your money and abruptly departs with no further explanation, but a great pity fills your heart for whomever it might be that he seeks. [D1/S2]</p>`,
	},
	803: {
		index: 803,
		text: `<p>The soldier accepts your gold, pledging his services to you. However, he disappears one dark night.</p>
<p><b>No Skill, Stealth and Stealing</b> (mandatory): Enraged, you pursue him, intent on punishing him for his treachery and greatly desiring the return of your gold, but never do you see him again. [D1/W-2 (Min: Poor)/<em>Envious</em>]</p>
<p><b>Piety:</b> You pray for him and leave word of your route before resuming your journey. Many days later he catches up with you and apologizes for his sudden departure, explaining that he left to pursue an old enemy, whom he miraculously defeated. He was told you prayed for his safety and, moved by your faith, swears to serve you and repay your trust. [D1/S1/Piety/Weapon Use (I use at Master level)]</p>`,
	},
	804: {
		index: 804,
		text: `<p>The soldier agrees to your terms, but is of little use to you. Finally you dismiss him, poorer and somewhat wiser. [D1/W-1 (Min: Respectable)]</p>`,
	},
	805: {
		index: 805,
		text: `<p>The solder ignores you completely. He is intent on achieving revenge.</p>
<p><b>No Skill:</b> You depart, hoping to find someone more interesting to speak to. [D1]</p>
<p><b>Storytelling:</b> You patiently insist that the other listen to you as you tell him the Tale of the Vengeful Camel and What Befell Him. He considers your tale carefully, then praises you before the Merciful God for showing him the error of his ways. [D2/S1/<em>Blessed</em> (1 turn)]</p>`,
	},
	806: {
		index: 806,
		text: `<p>As you humble yourself before him, he gazes closely upon your features and cries, "Aha! Aren't you the dog I have sworn to kill?"</p>
<p><b>No Skill:</b> "This act of obeisance is meant to deceive me!" He wounds you severely before he discovers his mistake, and he flees into the night. [D1/<em>Wounded</em>/<em>Crippled</em> (1 turn)]</p>
<p><b>Beast Form</b> (mandatory), <b>Appearance:</b> As he raises his sword, he gets a much better look at you. Your distinctive form could not long be mistaken for another. Realizing his mistake, the other apologizes profusely, and tells you the story of his vengeance—it is quite an interesting tale, and you promise to tell it to others that they might avoid the mistakes he has made. [D1/S2]</p>`,
	},
	807: {
		index: 807,
		text: `<p>You speak to the soldier, but he brushes aside your words. He growls, "The only thing I wish is the destruction of my enemy. Aid me and I will serve you."</p>
<p><b>No Skill:</b> You will have no part of such things, and you go on your way. [D1]</p>
<p><b>Weapon Use:</b> You offer your sword in his cause, and, with your help, his righteous vengeance is achieved. All who hear of your brave deeds think highly of them. [D1/S1/Weapon Use/<em>Respected</em>]</p>`,
	},
	808: {
		index: 808,
		text: `<p>The soldier is suspicious of you and constantly looks in all directions for hidden enemies. You note the fine make of his sword, and offer to buy it. At this, he howls, "I knew it! You have been sent by my enemies to rob me my defenses!"</p>
<p><b>No Skill:</b> He beats you soundly despite your protestations of innocence, and you flee from his madness. [D1/<em>Wounded</em>]</p>
<p><b>Piety:</b> Others come to your aid, protesting your innocence, for your virtue is well known. The soldier is chagrined by his error and offers you the service of his strong right arm for your protection to make up for the insult he has delivered. [D1/Weapon Use (1 use)]</p>`,
	},
	809: {
		index: 809,
		text: `<p>The young man seems anxious to pay you a high price for an item you believe is worthless.</p>
<p><em>You can sell it to him or keep it to examine later:</em></p>
<p><em>If you sell it:</em> You make a tidy profit. [D1/W+1 (Max: Rich)]</p>
<p><em>If you keep it, roll one die, adding one for Scholarship:</em></p>
<p>❖ 1–4: You suspect that is has value beyond what is obvious, and keep it. Later, you examine it but you find no evidence of special value. You should have let the fellow buy it. [Bargaining and Evaluation]</p>
<p>❖ 5+: You suspect that is has value beyond what is obvious, and keep it. You discover that it is a precious treasure! [D2/<b>Protective Talisman</b>]</p>`,
	},
	810: {
		index: 810,
		text: `<p>As you approach, the other favors you with a withering look. Something about his grim visage frightens you, and you move hastily away. [S1]</p>`,
	},
	811: {
		index: 811,
		text: `<p>As you try to steal the other's possessions, he returns and discovers you. He batters you and accuses you of many crimes.</p>
<p><b>No Skill:</b> Fortunately he soon tires of administering justice and, with a final kick to your backside, he hastens away. [D1/<em>Wounded</em>]</p>
<p><b>Beguiling:</b> You protest your innocence with your most convincing voice, but this simply further enrages the young man. He generously devotes his time to chastising you, beating you harshly with many blows to your face and body. [D1/Lose Appearance/<em>Wounded</em>]</p>`,
	},
	812: {
		index: 812,
		text: `<p>You snatch the soldier's purse and disappear before he can respond. Inside are a few coins and a worthless piece of children's jewelry.</p>
<p><b>No Skill:</b> Later, you hear that the jewelry once belonged to the soldier's dead sister, and that he has sworn to slay the one who stole it. [S1/<em>Pursued</em>]</p>
<p><b>Bargaining and Evaluation:</b> Such jewelry can be of no value but sentimental, and you have no wish to separate the soldier from those things which might bring him comfort. You sneak into his quarters and return it with an anonymous apology. [D1/Choice of Wisdom or Piety]</p>`,
	},
	813: {
		index: 813,
		text: `<p>The soldier is traveling in your direction and agrees to accompany you. Soon after, you are waylaid by a troop of vengeful soldiers. Their leader points to your companion and asks you, "Do you travel with this man?"</p>
<p><b>No Skill:</b> Fearful, you deny it. [Go to paragraph 1394]</p>
<p><b>Luck, Weapon Use:</b> With not the slightest fear, you say that you do, and the band of thugs draw their swords and rush you. Your companion cries out in fury and hurls himself forward, his blade tracing complex patterns through the air, and you stand at his back and join the fray. Though the fight is desperate, you are victorious, as much by luck as by the skill of your blade. Your companion is grateful for your aid, and wishes to accompany you as your bodyguard. [D1/S1/Weapon Use (Master level)]</p>`,
	},
	814: {
		index: 814,
		text: `<p>The soldier laughs in your face and observes that a man with his skill and renown would hardly serve one like you. He launches into a tirade about your worthlessness, full of degrading comments on manners of a most intimate nature.</p>
<p><b>No Skill:</b> This public mockery shames you. [D1/<em>Scorned</em>]</p>
<p><b>Courtly Graces:</b> You endure the soldier's coarse jests with dignity. In quiet tones, you express your disdain for his lack of manners and breeding, and conclude that no more can be expected from one of his low kind. Finally, in an explosion of insults, he departs. Others rush to you and praise you for your calm defense against this loathsome harangue, and they congratulate your courage in standing up to this bully. [D1/S1/<em>Respected</em>]</p>`,
	},
	815: {
		index: 815,
		text: `<p>The other names a sobering high fee. Initially appalled, after a brief demonstration of his prowess you agree that his services would well be worth that sum.</p>
<p><b>No Skill:</b></p>
<p><em>If you have wealth greater than Poor, you may pay his price or decline:</em></p>
<p><em>If you cannot or will not pay his price:</em> Although you are very impressed, you decline. He takes no offense, and looks for another patron to hire him. [D1/Bargaining and Evaluation]</p>
<p><em>If you pay the price:</em> You agree to the exorbitant price, and the soldier becomes your bodyguard. [D1/W-3 (Min: Beggar)/Weapon Use (Master level)]</p>
<p><b>Bargaining and Evaluation:</b> Cleverly, you tell the other of the potential of your business enterprises, and convince him to accept a share of the profits as his fee. [D1/Weapon Use at Master level]</p>`,
	},
	816: {
		index: 816,
		text: `<p>You observe the other as he boasts his exploits to an admiring crowd. As evening falls, you follow him to his quarters.</p>
<p><b>No Skill:</b> You discover his sleeping-chamber, but his window is high and inaccessible, and you depart, frustrated. [Stealth and Stealing]</p>
<p><b>Stealth and Stealing, Quick Thinking:</b> You climb over the roof and into his room. He is sound asleep. You steal his purse and sword easily. Soon, you discover the sword is magical, the source of his power. [D2/S1/<b>Thunderbolt Sword</b>]</p>`,
	},
	817: {
		index: 817,
		text: `<p>As you grab the great man's purse, your wrist is clamped in an iron grip. "Since Allah frowns upon those who abuse the foolish, I will not kill you," he says. "But do not attempt such a deed again." [D1/<em>Outlaw</em>]</p>`,
	},
	818: {
		index: 818,
		text: `<p>The other is far more skilled than you supposed. He toys with you, slashing your garments to shreds and tracing tiny wounds with his razor-sharp sword.</p>
<p><b>No Skill:</b> Finally you collapse. He kicks dust on you, spits, and leads the crowd as they hurl rotted fruits at you. You flee, but your shame follows you. [D1/<em>Scorned</em>]</p>
<p><b>Acting and Disguise:</b> You collapse to the ground as if you had fainted. When the other draws near, you grab his leg, toppling him to the ground. The crowd cheers your cleverness as you make good your escape. [D1/S1]</p>`,
	},
	819: {
		index: 819,
		text: `<p>You don't have a chance against this other. You quickly realize your folly, throw down your weapon, and plead for mercy. He spits on you and laughs. [D-1/<em>Scorned</em>]</p>`,
	},
	820: {
		index: 820,
		text: `<p>He is the finest, cleverest, and least honorable swordsman in the land. Even a master might fall to this other.</p>
<p><b>No Skill:</b> He teases you with false hope—imagined openings, feigned fatigue—then, when he tires of the sport, he casually disarms you and humiliates you. He drags you before the Sultan for punishment, and the Prince of the Faithful orders you to serve the swordsman as his slave. [D-1/S1/<em>Enslaved</em>]</p>
<p><b>Luck:</b> Overconfident, he tries to lure you into careless attacks by feigning fatigue and dizziness—but he overacts. You catch him off-guard and are on him like a hound on a rat. You know you could never have defeated him without his foolish ploy, and you praise your good fortune as you hurry away from your unconscious foe. Your reputation grows to legend overnight, for few have defeated this fearless lion. [D2/S2/Weapon Use/<em>Respected</em>]</p>`,
	},
	821: {
		index: 821,
		text: `<p>At your sweet words, he says, "I think of my lost lover ceaselessly but must put my heart aside and accept your kind offer."</p>
<p><b>No Skill:</b> He is faithful and dutiful but cannot forget his true love. You know cannot find happiness in such a union, and sadly depart, never again to see him. [D1/<em>Grief Stricken</em>]</p>
<p><b>Appearance, Courtly Graces:</b> Your charm diverts the other's sorrow, and your prospects together are encouraging. [D1/<em>Beloved</em>]</p>`,
	},
	822: {
		index: 822,
		text: `<p>At your words, he replies, "You are kind, but it can never be. I have a lover at sea, torn from me by cruel fate... and her cruel parents. If you love me, help me to join my lover."</p>
<p><b>No Skill, Appearance</b> (mandatory), <b>Seduction</b> (mandatory): Stung by rejection but driven by pride you press your suit. The frustration and humiliation is too much to bear. Yet he does not waver from his devotion, and you must leave before the sorrow tears you apart. [S1/Choice of Lose Appearance or Lose Seduction/<em>Grief Stricken</em>]</p>
<p><b>Quick Thinking:</b> The challenge of aiding the other is appealing. You quickly concoct a scheme to bring the young lovers together, and so craftily you work that the parents never know they have been hoodwinked. The lovers praise you and make you the guest of their household for many days. [D2/S1/<em>Blessed</em>]</p>`,
	},
	823: {
		index: 823,
		text: `<p>He says, "Your attentions are most unwelcome at this time, for my lover is dead and I wish only to be with my family and friends." You acknowledge the pain that causes such discourtesy, and politely you withdraw. [D1]</p>`,
	},
	824: {
		index: 824,
		text: `<p>Alone and distraught in an unfamiliar land, the other encourages your attentions.</p>
<p><b>No Skill:</b> You soon regret ever having spoken to him, for homesickness brings nothing but unhappiness and bitterness to him. Though you part on unfriendly terms, you cannot put your lover from your heart. [D1/<em>Grief Stricken</em> (1 turn)]</p>
<p><b>Wisdom:</b> You realize the other is unhappy and must return home. You are married, and he travels to his homeland to await you, to live ever after in happiness.</p>
<p><em>Roll one die to determine your new homeland and place your Origin marker in this new city: 1–2: Bilma; 3–4: Daybul; 5–6: Kiev.</em> [D2/S2/<em>Married</em>]</p>`,
	},
	825: {
		index: 825,
		text: `<p>The other tells you of his sorrow. "The shipwreck which I suffered has left me wretched. I cannot remember the land of my birth, and I am destitute of family, friends, and wealth."</p>
<p><b>No Skill:</b> There is nothing you can do to aid the other, and you go your way. [S1]</p>
<p><b>Wilderness Lore, Seamanship:</b> When the other describes the customs of his home, you recognize from his speech the land of Serendib. You offer to accompany him there... for appropriate consideration, of course. Gratefully, the other accepts. [D2/Place your Destination marker in Serendib and choose a random <b>Treasure</b> without looking at it. If you arrive at Serendib, you receive the <b>Treasure</b>]</p>`,
	},
	826: {
		index: 826,
		text: `<p>As you propose a business deal to the other, he cries out, "You would take advantage of my desperate situation to drive a hard bargain? Pfah! I would never deal with such a dishonorable one."</p>
<p><b>No Skill:</b> You cannot prove your honesty, and nothing comes of your offer but a tarnished reputation. [D1/<em>Scorned</em> (1 turn)]</p>
<p><b>Courtly Graces:</b> Your reputation is without blemish, and those around verify your integrity. Seeing the truth, the other deals fairly with you. [D1/W+1 (Max: Princely)/Bargaining and Evaluation]</p>`,
	},
	827: {
		index: 827,
		text: `<p>The other seeks an enchanted site on a fabled island and would give a great deal to reach it.</p>
<p><b>No Skill:</b> You've no notion of how to find this place, nor whether it even exists. You both go away no richer. [S1]</p>
<p><b>Scholarship:</b> Through research you discover the other's destination is far through the barbarian lands of the north and west. Though difficult, the journey is possible for one of stout heart. You are well paid for your information, and the other offers to take you with him on his expedition. [D2/W+2 (Max: Rich)/Opportunity to enter Stonehenge]</p>`,
	},
	828: {
		index: 828,
		text: `<p>The other quickly accepts your offer of employment.</p>
<p><b>No Skill:</b> As might be expected when you hire someone who doesn't know where he is, you are somewhat disappointed with the quality of his services. [D-1/S1/Choice of Lose Quick Thinking or Lose Wisdom]</p>
<p><b>Luck</b> (mandatory): Though the other is most unprepossessing, you are used to following hunches, and you are perversely confident of this person's usefulness. You follow your hunch into deep trouble, and barely escape alive. [D-1/S1/W-1 (Min: Poor)/Lose Luck/Lose Wisdom]</p>`,
	},
	829: {
		index: 829,
		text: `<p>You recognize the talents of the other. Further, you realize that, since he is lost, he is at your mercy, and his services may be had at a fraction of their true worth.</p>
<p><b>No Skill:</b> You deduce his destination but conceal it to keep him dependent a while, for his services are quite valuable. [D1/W+1 (Max: Respectable)]</p>
<p><b>Courtly Graces:</b> Honor commands you to reveal the other's destination, and you offer him your aid in reaching it. Impressed, he reveals he is a powerful noble in his land and rewards you for your kindness. [D2/W+1 (Max: Rich)/<em>Blessed</em> (1 turn)/<b>Treasure</b>]</p>`,
	},
	830: {
		index: 830,
		text: `<p>The other agrees to work for you. Over time you realize the other is talkative—very talkative—incessantly talkative! Finally, you conclude that you must dismiss him if you are ever to get anything done. [D1/Wisdom]</p>`,
	},
	831: {
		index: 831,
		text: `<p>The other accepts your kind offer, but he is distracted by melancholy and cannot perform his required duties.</p>
<p><b>No Skill:</b> You are forced to dismiss this useless companion. [D1]</p>
<p><b>Piety:</b> The other is deeply depressed, but your example of faith and resolution makes an impression on him. Over time, the other finds solace and performs admirably. [D2/Piety/Choice of Bargaining and Evaluation or Weapon Use]</p>`,
	},
	832: {
		index: 832,
		text: `<p>Never before have you encountered so bitter and critical a soul. Never happy, always complaining, the other soon drives you to distraction.</p>
<p><b>No Skill:</b> You regret your stupid decision to hire this wretch and, for your own sanity, dismiss him. When you do, he bitterly rails against and vilifies you with such anger that others believe that you have sorely wronged him. [S1/<em>Scorned</em>]</p>
<p><b>Enduring Hardship:</b> The other is a skilled worker, so you tolerate his annoying personality, for you have undergone much worse than a complaining companion. As you praise his work, his disposition improves, and in the fullness of time you benefit greatly from his diligence. [D1/W+1 (Max: Respectable)/Choice of Bargaining and Evaluation or Scholarship]</p>`,
	},
	833: {
		index: 833,
		text: `<p>He replies, "I am already spoken for. I am sorry."</p>
<p><b>No Skill, Seduction</b> (mandatory), <b>Appearance</b> (mandatory): Unaccustomed to rejection, you press your suit. Your shameful actions are discovered, and you are punished for adulterous conduct. [D1/<em>Imprisoned</em>]</p>
<p><b>Courtly Graces:</b> Your charms are so captivating that you are offered an introduction to the other's older brother, who turns out to be even more handsome and charming! [D1/S1/<em>Beloved</em>]</p>`,
	},
	834: {
		index: 834,
		text: `<p>The other is virtuous and honorable and loves you deeply, but cannot abandon his aged mother.</p>
<p><b>No Skill:</b> You depart with tears flowing down your face for the loss of the love of one so noble. [D1/<em>Grief Stricken</em>]</p>
<p><b>Seduction, Appearance:</b> Your beauty and your skillfully woven protestations of love overwhelm him, and he surrenders himself to you. Blinded by passion, the other goes away with you. Your love is strong, but your lover is consumed with remorse. [D1/S1/Lose Wisdom/<em>Grief Stricken</em>/<em>Beloved</em>]</p>`,
	},
	835: {
		index: 835,
		text: `<p>The other is smitten with you and swears to follow wherever you go. However, you later discover he is a member of the Sultan's bodyguard and has been arrested for desertion.</p>
<p><b>No Skill:</b> He is imprisoned, and you are tragically separated. [D1/S1/<em>Grief Stricken</em>]</p>
<p><b>Storytelling:</b> You go to the Sultan to plead for your lover. Your impassioned, skillful, and pious defense touches the Sultan's heart, and your wisdom is praised by all. Your lover is pardoned and joyfully rejoins you. [D2/S1/Courtly Graces/<em>Beloved</em>]</p>`,
	},
	836: {
		index: 836,
		text: `<p>Despite the other's incessant chatter, you take him on. In time you discover the folly of imprudent charity as you endure his yammering. [D1/<em>Insane</em> (1 turn)]</p>`,
	},
	837: {
		index: 837,
		text: `<p>The other's words confuse you as you try to follow his obscure suggestions.</p>
<p><b>No Skill:</b> You are confused and come away rather badly swindled. [S1/W-1 (Min: Respectable)]</p>
<p><b>Bargaining and Evaluation:</b> You are too experienced to make deals when you are confused. You make him repeat himself until you understand. [D1/W+1 (Max: Respectable)/Bargaining and Evaluation]</p>`,
	},
	838: {
		index: 838,
		text: `<p>The other's ceaseless babbling drives you crazy. Finally, your patience fails, and you lose your temper.</p>
<p><b>No Skill:</b> The other stalks away in a huff. No one profits from such unpleasantness. [Scholarship]</p>
<p><b>Enduring Hardship:</b> You endure the idle chatter peaceably and politely. Finally, the other gets down to business and is quite sensible and reasonable. [D1/W+1 (Max: Rich)/Bargaining and Evaluation]</p>`,
	},
	839: {
		index: 839,
		text: `<p>Bargaining with this jabbering magpie is endlessly frustrating. A stream of dull reminiscences—travels, family, and social triumphs—pour from him.</p>
<p><b>No Skill:</b> You politely excuse yourself before you are bored unto death. [S1]</p>
<p><b>Beguiling:</b> You pretend great interest in his babblings, and he regards you as a friend and wise companion. You thereupon proceed to swindle him repeatedly. [D2/S1/W+2 (Max: Rich)]</p>`,
	},
	840: {
		index: 840,
		text: `<p>The other is proud of his prowess and battle experience. He demands a high price, but to reach your destination you must travel through a very dangerous area.</p>
<p><b>No Skill:</b> <em>You may pay him or decline:</em></p>
<p><em>If you decline:</em> Brigands are indeed waiting for you. They beat you, rob you, and leave you for dead. [S1/W-2 (Min: Penniless)/<em>Wounded</em>]</p>
<p><em>If you accept:</em> You pay his price and hope that he is as good as he says. [W-2 (Min: Poor)/Go to paragraph 1395]</p>
<p><b>Weapon Use:</b> When bargaining with the other, you propose to test his skills against your own. After a brief passage at arms, you gain the advantage, and his pride is somewhat deflated. He adjusts his price accordingly. [D1/Go to paragraph 1395]</p>`,
	},
	841: {
		index: 841,
		text: `<p>The other declines your offer, saying, "I'm sorry, but I have pressing business elsewhere."</p>
<p><b>No Skill:</b> You accept the refusal and go on your way. [D1]</p>
<p><b>Courtly Graces:</b> Out of courtesy, you promptly offer him your aid. Shamed by your generosity and grace, he reconsiders. You strike a mutually agreeable bargain. [D1/Choice of Weapon Use or Quick Thinking]</p>`,
	},
	842: {
		index: 842,
		text: `<p>The other is careful and asks you for references.</p>
<p><b>No Skill:</b> Nothing but good is to be heard about you, and the other is happy to serve you. You are quite satisfied with the services. [D1/Choice of Wilderness Lore or Bargaining and Evaluation]</p>
<p><b>Stealth and Stealing, Scorned, Outlaw</b> (All mandatory): When he learns of your past, he says, "Your reputation is stained, and I cannot work for you." [D1]</p>`,
	},
	843: {
		index: 843,
		text: `<p>This person has valuable skills and agrees that what you offer is a fair price, but he hesitates to leave his secure employment for a more adventurous life.</p>
<p><b>No Skill:</b> Regretfully you must search for another person. [Bargaining and Evaluation]</p>
<p><b>Storytelling:</b> Your animated tales of the exciting life you lead are so intriguing that the other is swayed and agrees to accompany you. [D1/S1/Choice of any skill (I use)]</p>`,
	},
	844: {
		index: 844,
		text: `<p>The other is cool to your proposals, and seems absorbed with other matters. You dedicate yourself to the costume arts for the next time you find yourself in such a position. [Choice of Appearance or Acting and Disguise]</p>`,
	},
	845: {
		index: 845,
		text: `<p>The other is surprised at your interest in his belongings, for they are merely things he has gained here and there. He listens politely to your offer.</p>
<p><b>No Skill:</b> You manage to strike a bargain for a few items, but the other senses the value of certain items and is reluctant to part with them. [D1/W+1 (Max: Respectable)]</p>
<p><b>Luck, Bargaining and Evaluation:</b> You are most persuasive, and convince him to sell you a number of rare and interesting items. [D1/Choice of W+2 (Max: Rich) or <b>Treasure</b>]</p>`,
	},
	846: {
		index: 846,
		text: `<p>He wears a splendid ring. You know you must own it or die—but he refuses to sell it.</p>
<p><b>No Skill:</b> You are obsessed with the ring, and cannot rest until you have it. [D1/<em>Envious</em>]</p>
<p><b>Beguiling:</b> You contrive a story which presents the ring as an ancient heirloom of your family. Moved, the other surrenders it to you. [D2/W+1 (Max: Respectable)]</p>`,
	},
	847: {
		index: 847,
		text: `<p>The other is desperate and needs money badly. This means that he has nothing to offer you but his services, for which you have no immediate need.</p>
<p><b>No Skill:</b> You can't see paying money for something you don't need. [Bargaining and Evaluation]</p>
<p><b>Piety:</b> Something—perhaps sympathy for the unfortunate, which is the duty of all the Faithful—impels you to hire him anyway. Your impulse is fortunate, for the other's skills come in handy. [D1/Choice of any skill (I use)]</p>`,
	},
	848: {
		index: 848,
		text: `<p>In trading with the other you obtain an item you believe to be of great value. It seems quite a bargain and promises to yield a great profit when sold.</p>
<p><b>No Skill:</b> Alas, when you present the item to a merchant to sell it, you discover it is a worthless fake. The merchant is kind to you, though, and teaches you to avoid such mistakes in the future. [D-1/S1/W-1 (Min: Penniless)/Bargaining and Evaluation]</p>
<p><b>Bargaining and Evaluation:</b> Careful scrutiny indicates the item's true worth, and you avoid an unwise purchase. You profit greatly from trading with him. [D1/W+1 (Max: Respectable)/Bargaining and Evaluation]</p>`,
	},
	849: {
		index: 849,
		text: `<p>The fool is trusting and eager to trade. He accepts junk in return for valuable goods.</p>
<p><b>No Skill:</b> You make a substantial profit at his expense. [D1/W+1 (Max: Respectable)]</p>
<p><b>Courtly Graces:</b> You principles prevent you from cheating the poor soul and from making a profit. [D1/Piety]</p>`,
	},
	850: {
		index: 850,
		text: `<p>You are swept up with passion for the other, and you spend an evening whiling away the hours in most intimate entertainment. Only when the other makes to leave do you learn of the other's spouse!</p>
<p><b>No Skill:</b> Humiliated, you accept your unwise action and withdraw. [D1/<em>Grief Stricken</em> (1 turn)]</p>
<p><b>Beguiling:</b> You set a trap for the other and obtain indisputable evidence of his infidelity, then blackmail him with a threat to reveal all. [D1/S1/W+1 (Max: Rich)]</p>`,
	},
	851: {
		index: 851,
		text: `<p>Believing you interested only in his wealth, he rejects your suit.</p>
<p><b>No Skill:</b> You accept your fate and depart, knowing you have a good heart but not knowing how to prove it. [D1]</p>
<p><b>Appearance:</b> The next day, though, you meet him again. The beauty of your eyes and the grace of your form captivate him and he cannot be parted from you. He composes poems to you of the most surpassing loveliness, comparing your beauty to the light of the brightest stars. [D2/W+1 (Max: Rich)/<em>Beloved</em>]</p>`,
	},
	852: {
		index: 852,
		text: `<p>The other is rich, well-figured and, you hope, fine material for marriage.</p>
<p><b>No Skill:</b> However, the cheating that made him rich is the same that abuses your affections. Your misery is unbearable when you discover his infidelity, and sorrow fills your heart as you divorce him. [D1/<em>Grief Stricken</em>]</p>
<p><b>Seduction, Stealth and Stealing:</b> Only one with your flexible principles could keep such a person "honest." In fact, you are a fine pair of schemers. [D2/S1/Bargaining and Evaluation/Quick Thinking/<em>Married</em>]</p>`,
	},
	853: {
		index: 853,
		text: `<p>You haggle for hours, and many coins and goods change hands.</p>
<p><b>No Skill:</b> Later you examine your trades carefully and suspect that the other fellow got the best of the deals. You consider your errors carefully, and feel that you have learned much about commerce. [D1/W-1 (Min: Poor)/Bargaining and Evaluation]</p>
<p><b>Bargaining and Evaluation:</b> Your bargaining skills are equal to his, and you make a fair profit. [D1/W+1 (Max: Rich)]</p>`,
	},
	854: {
		index: 854,
		text: `<p>"Buy these wares!" hawks the other. "My family is terribly needy!"</p>
<p><b>No Skill:</b> You buy the man's goods out of sympathy, only to discover too late their poor quality. You resolve to learn how better to judge the goods you purchase. [D1/W-1 (Min: Poor)/Bargaining and Evaluation]</p>
<p><b>Bargaining and Evaluation:</b> A second's examination convinces you that the other's wares are junk. You waste no time with weasels. [D1/S1/Bargaining and Evaluation]</p>`,
	},
	855: {
		index: 855,
		text: `<p>"If you lend me the sum I need," says the other, "I have an investment that will return your money fivefold." You never see your coins again. [D1/W-1 (Min: Poor)/Wisdom]</p>`,
	},
	856: {
		index: 856,
		text: `<p>He asks you to assist him in a swindle. You are to play the part of a foreign scholar, and verify the value of several false items he hopes to sell to a wealthy collector.</p>
<p><b>No Skill:</b> You bungle the job by not knowing certain facts about the land you are supposed to be from. You and your conniving companion must flee for your lives. [S1/<em>Outlaw</em>]</p>
<p><b>Scholarship, Bargaining and Evaluation:</b> Ironically, you recognize that one of the "false" items is of real value. You betray the swindler to the authorities and keep this piece. [D2/S1/<em>Respected</em>/<b>Treasure</b>]</p>`,
	},
	857: {
		index: 857,
		text: `<p>The swindler scurries from you, squealing in terror. You pursue him but realize you are surrounded by the coward's bodyguards.</p>
<p><b>No Skill:</b> Resistance would be futile. You are forced to surrender, and they throw you in a cell. [D1/<em>Imprisoned</em>]</p>
<p><b>Weapon Use:</b> You draw your weapon with a flourish. Daunted, the bodyguards step aside. You corner the cheating merchant and deal with him justly, to the approval of all. [D1/S1/<em>Respected</em> (1 turn)]</p>`,
	},
	858: {
		index: 858,
		text: `<p>Infuriated by the dishonest merchant's refusal to deliver on time, you draw your scimitar and threaten the vermin. He howls and pleads his innocence.</p>
<p><b>No Skill:</b> The other merchants take his side, forcing you to withdraw your claim. You stalk off, fury and greed consuming your soul. [D1/<em>Envious</em>]</p>
<p><b>Respected</b> (mandatory), <b>Courtly Graces:</b> Your stainless reputation is above reproach, and the other merchants side with you. You take the case before the Sultan, and he orders your monies restored and the swindler banished. [D1/S1/W+1 (Max: Respectable)]</p>`,
	},
	859: {
		index: 859,
		text: `<p>A merchant of this sort is accustomed to angry customers. When you threaten him, a concealed wire net drops on you. His bodyguards deal most unpleasantly with you, beating you soundly and throwing you out into the alley behind the store. [D-1/S1/<em>Wounded</em>/<em>Envious</em>]</p>`,
	},
	860: {
		index: 860,
		text: `<p>Intent on revenge, you enter the merchant's house to claim compensation. Normally, the pig's dwelling is well-guarded, but luck—or Allah's justice—has made the guard sleepy. You discover a vast trove and grab what you can. Unfortunately, the merchant discovers you with your arms full of his ill-gotten goods, and you flee.</p>
<p><b>No Skill:</b> [D1/S1/W+1 (Max: Respectable)]</p>
<p><b>Luck, Scholarship:</b> Later, you realize that among the items you snatched are several quite extraordinary gems. [D2/S1/W+1 (Max: Respectable)/<b>Ionian Gems</b>]</p>`,
	},
	861: {
		index: 861,
		text: `<p>The house is unguarded. You marvel at your luck and begin to help yourself to the abundant wealth. Alas! It is a trap! The merchant and four armed men appear from hiding. "I've dealt with your kind before," he says. "In fact, I started my career as a robber. But I had the sense to never get caught."</p>
<p><b>No Skill:</b> His bodyguards throw you in a cell to teach you a lesson. [D1/<em>Imprisoned</em>]</p>
<p><b>Storytelling, Acting and Disguise:</b> You remind him of the circumstances that once drove him to theft and then plead your own desperate case. "There but for the grace of Allah go I," he acknowledges, and moved by the memory of his own youth, he sets you free. [D1/S1]</p>`,
	},
	862: {
		index: 862,
		text: `<p>You do not wish to meet the other, and he does not press. You go your separate ways, but you work on your desirability nonetheless. [Appearance]</p>`,
	},
	863: {
		index: 863,
		text: `<p>The other watches as you head away, and you feel yourself being stared at the whole time.</p>
<p><b>No Skill:</b> You can't be bothered and continue walking. [D-1]</p>
<p><b>Seamanship:</b> You decide to stop; you have not heard of the other causing trouble in this part of the world and a friendly greeting might secure relations with the other. The other proves to be friendly and talkative. Your knowledge of the oceans of the world impresses him and when it is time for the other to leave, you are given a great gift. [D1/S2/<b>Colored Fish</b>]</p>`,
	},
	864: {
		index: 864,
		text: `<p>The other watches as you head away, and you feel yourself being stared at the whole time.</p>
<p><b>No Skill:</b> You decide to stop but when you turn around the other is not there. [D1]</p>
<p><b>Scholarship:</b> You decide to stop and make contact; at least the meeting might enrich your knowledge of the other. After introducing yourself, the other proves to be friendly and talkative, and tells you many wondrous tales. [D1/S2]</p>
<p><b>Seamanship:</b> You decide to stop; the other proves to be friendly and talkative. Your knowledge of the oceans of the world impresses him and before he leaves, you are told of a most wondrous place. [D2/S2/Opportunity to enter the Lake of Colors]</p>`,
	},
	865: {
		index: 865,
		text: `<p>"Who are you to waste my time with trifles," says the other, "You are too lowly to truly honor me. I should punish you for wasting my time!"</p>
<p><b>No Skill:</b> You think a hasty retreat is best and walk backwards from the other bowing a scraping all the way. You are ignored before you are even gone. You determine yourself to learn more of high stations before trying to honor another. [D1/Courtly Graces]</p>
<p><b>Acting and Disguise:</b> "I am from the great college of enchanters," you reply, "and my manner is that of one who spends too much time with books, I'm afraid." The other is convinced and is honored to be noted by such a scholar as you claim to be. You dine and enjoy an evening of entertainment where you press your new-found position to more romantic ends. [S2/Seduction]</p>`,
	},
	866: {
		index: 866,
		text: `<p>"Honor me, do you? If you truly with to honor me then you will help me with a little scheme I have." The other explains that you will be only temporarily turned into an ape so that you can sneak onto an evil Vizier's property and take back a stolen statue from his gardens. If you are caught, the groundsmen will think nothing of an animal in the garden and will simply shoo you away.</p>
<p><b>No Skill:</b> You listen to the scheme and it seems quite reasonable to you. You go along with it only to find that there is nothing temporary about your condition. You cannot demand your share of the reward as no one will listen to one who has been seemingly so punished by Allah. [S1/<em>Beast Form</em>]</p>
<p><b>Acting and Disguise:</b> You make a small alteration to the plan—you will wear an ape costume instead. You are indeed spotted by the groundsmen but they pay you no mind. They don't even shoo you away. Seeing you near the statue the groundsmen begin to talk about its value. When they leave you steal the statue and bring it back to the other, prepared to renegotiate now that you know the true value of the thing. [S1/Bargaining and Evaluation]</p>`,
	},
	867: {
		index: 867,
		text: `<p>You honor the other from a quite hiding place. The other passes you by unnoticed. [D1]</p>`,
	},
	868: {
		index: 868,
		text: `<p>The other turns briefly your way, but seems not to notice you.</p>
<p><b>No Skill:</b> When you are sure it is safe, you emerge from hiding and journey onward. [S1]</p>
<p><b>Scholarship:</b> Truly you wish you were not so afraid as to hide because the study of this magnificent other might have yielded much wisdom. Still, even a brief glimpse of this worthy gives you much material to spin a fine tale. [S2]</p>`,
	},
	869: {
		index: 869,
		text: `<p>Your hiding place is well-chosen, and you are not found by the other. Eventually, you come out and journey on. [S1]</p>`,
	},
	870: {
		index: 870,
		text: `<p>You see the brigands from a distance, and hide yourself from them. They do not seem to see you, and when they are gone, you travel on. [D1]</p>`,
	},
	871: {
		index: 871,
		text: `<p>You hide yourself to avoid being seen. The brigands are so involved in their merry-making that they do not notice you. [S1]</p>`,
	},
	872: {
		index: 872,
		text: `<p>It is no challenge to avoid them, so deeply are they in their cups.</p>
<p><b>No Skill:</b> Off you head to better places. [S1]</p>
<p><b>Stealth and Stealing:</b> You cannot resist such an easy mark. You sneak into their camp as they lie snoring and make your escape with some bags of gold. [S1/W+1 (Max: Respectable)]</p>`,
	},
	873: {
		index: 873,
		text: `<p>You follow the other into the wilderness. So intent are you on your prey that you don't notice where you're going. The other is a mere hermit and you decide to move on.</p>
<p><b>No Skill:</b> You are lost in the forest but following the other you saw how he survived off the land. You do the same until you are in familiar territory. [S1/Wilderness Lore]</p>
<p><b>Wilderness Lore:</b> You are not sure where you are but you know that you can live off of the forest until you figure it out. [S1]</p>`,
	},
	874: {
		index: 874,
		text: `<p>The other boards a ship and you are not sure how you will be able to follow. Just as you are about to give up a sailor notices you. "Are you here to join the crew?" he asks.</p>
<p><b>No Skill:</b> You say that you are but that you don't know anything about being a sailor. The other says that they are short crew members and that they will teach you along the way. You learn a trade and continue to spy on the other. The skill gained from the former proves handy, the results of the latter are fruitless. [Seamanship]</p>
<p><b>Seamanship:</b> "Am I too late?" you ask. "No," says the other. The new captain is the one who is late." Thinking quickly and forgetting the one you follow you ask, "Have you ever met this new man?" "Not as yet," says the sailor. "Then perhaps you should be more careful who you are disrespectful around!" You clap the other upside the head and say, "I'm the new captain and was testing you! Now set for sail before I clap you again!" You procure the ship owner's orders from the first mate and work making a fine living as the captain for some months—until you are set to meet with the ship owner. You disappear in the night before your meeting. [D2/W+2 (Max: Rich)/Acting and Disguise]</p>`,
	},
	875: {
		index: 875,
		text: `<p>You follow the other and travel on foot for many miles. You eventually say out loud that a steed would be most welcome. Then, there before you, a horse—and it wears no harness! You pray that this fine beast might be yours.</p>
<p><b>No Skill:</b> Despite your prayers the horse wanders out of sight. [S1]</p>
<p><b>Appearance:</b> The creature seems drawn to you and responds comfortably to your touch. Your prayers have been answered! [D1/Piety]</p>`,
	},
	876: {
		index: 876,
		text: `<p>Your most prized possession, a fine mare, is about to give birth, but her labor is difficult.</p>
<p><b>No Skill:</b> Sadly, both are carried away by the will of Allah. [D1/W-1 (Min: Respectable)/<em>Grief Stricken</em>]</p>
<p><b>Wilderness Lore, Scholarship:</b> Thanks to your learning, you are able to save both beasts. The offspring reflects the finest qualities of its parents. [D2/W+1 (Max: Rich)]</p>`,
	},
	877: {
		index: 877,
		text: `<p>Before you rides a prince on a horse of unsurpassed beauty, and you thank Allah for granting you this sight. Suddenly, the prince stops and cries out, "This stallion has this very day become the father of twin colts. In celebration of the bounty of Allah, one shall be given away to..." [he throws a coin, which lands at your feet] "...you!" The colt is as valuable as its father. [D1/S1/W+1 (Max: Rich)/Piety]</p>`,
	},
	878: {
		index: 878,
		text: `<p>The road ahead appears to be writhing and moving. To your horror, you realize it is covered with a mass of black snakes! They move with a purpose. In fact, they seem to be feeding.</p>
<p><em>You may turn back the way you came or try to discover upon what they feed:</em></p>
<p><em>If you turn away:</em> You know to leave feeding snakes alone. [D1]</p>
<p><em>If you wish to see their meal:</em> You attempt to knock aside the snakes. [Go to paragraph 1388]</p>`,
	},
	879: {
		index: 879,
		text: `<p>As you travel through the countryside, a young man on a horse gallops frantically toward you. "Flee! They come!" he cries. Boldly, you decide to stand and challenge those who fill the horseman with terror. They are skeletal forms—gools perhaps, or some horrible dead creatures.</p>
<p><b>No Skill:</b> Fear clouds your mind... you reel... When you awaken you are battered, bruised, and most of your possessions are missing. [D1/S1/W-2 (Min: Poor)]</p>
<p><b>Scholarship:</b> These are no beasts, but rather the "Restless Dead"—infidels who died without realizing the True Faith. Fortunately, you know prayers and words to dispatch them. [D1/S2/Piety]</p>`,
	},
	880: {
		index: 880,
		text: `<p>In your lodging, a strange voice whispers your name.</p>
<p><b>No Skill:</b> Suspecting evil, you leap from bed, shouting and laying about with your sword. Others come to your aid but are irritated by your silly tale, for there is no sign of wrongdoing nor indeed anything untoward. [D-1/S1/<em>Scorned</em> (1 turn)]</p>
<p><b>Enduring Hardship, Golden Bridle:</b> The peace you feel at the sound of the voices tells you they mean no harm. Wisely, you await the morning, and the crowing of the rooster drives the voices away. [D1/S1]</p>`,
	},
	881: {
		index: 881,
		text: `<p>You stumble upon a Magian fire-worshipping ceremony. Strange creatures flicker in the flames. The Magians, in their red turbans, turn and gaze upon you.</p>
<p><b>No Skill:</b> You draw your sword and attack but your trembling hand will not obey. Flaming dogs leap from the fire and overwhelm you. The Magians bind you, toss you into a smoldering coal-pit, and leave you for dead. Only Allah preserves your miserable life. [D1/S1/<em>Wounded</em>]</p>
<p><b>Enduring Hardship:</b> In the name of Allah, you draw your sword and lay about mercilessly, though you are outnumbered. Your unceasing attack sends them howling and fleeing in all directions, and the strange fire-beasts scatter into the night. Your great deeds are reported to the Sultan, who showers you with honor. [D2/S2/<b>Robe of Honor</b>]</p>`,
	},
	882: {
		index: 882,
		text: `<p>At night, before your eyes a dark shadow passes over the moon, bringing great fear to your heart, and a sword in your hand. Of a suddenness, a bird of solid black swoops toward you.</p>
<p><b>No Skill:</b> Barely can you hear the sound of its wings over your cries, and you flee—head-first into a wall, knocking yourself senseless. When you become again conscious, the night and its fearsome magpie are long gone—as are your wits. [D1/<em>Insane</em> (1 turn)]</p>
<p><b>Weapon Use:</b> With a flash of moonlight off its polished steel, your sword finds the creature's eyes and it falls dead at your feet. You prudently head towards your lodging without further delay. [D1/S2/Weapon Use]</p>
<p><b>Golden Bridle:</b> With a quick thought, you bring forth the Golden Bridle. The bird submits to your will, and you ride it like a gentle pony to a distant and magical place. [D2/S1/Move to any Place of Power and have an immediate encounter]</p>`,
	},
	883: {
		index: 883,
		text: `<p>By the will of Allah, a great crowd of small white birds has descended upon you. They do you no harm, but their unceasing cries and foul droppings threaten to drive you mad, nor do they fail to steal away many small belongings, tearing at your clothes and plucking your hair.</p>
<p><b>No Skill:</b> You curse them with a thousand vile epithets, and flail at them with your fists and sword, but better you would be to have tried to drain the ocean with a spoon, for you never manage to hurt a one. Their foul dung coats you head to foot. Finally, in one moment, they lift and fly away, their cries sounding as mocking laughter. [D-1/S1/<em>Scorned</em> (1 turn)]</p>
<p><b>Wilderness Lore:</b> You hold out food and make soft noises, and in this way you lure a bird close to you. Quickly you seize it by the neck, and wring the life from it. Its piteous cry serves as an effective communication to the other birds, who depart as quickly as a cutpurse who sees the Sultan's guards. [D1/S1]</p>`,
	},
	884: {
		index: 884,
		text: `<p>Above you, in a tree, you spy a small flock of Red Cockerel—a most rare and valuable bird. Eagerly you give it chase, hoping to trap them.</p>
<p><b>No Skill:</b> The birds dart from tree to tree until, wearied, you abandon the chase. [S1]</p>
<p><b>Enduring Hardship:</b> You follow relentlessly, until (by the will of Allah!), one lands just within your reach. You seize it up and gently wrap it that you might carry it without harm. Later you sell it for a pretty sum. [D1/W+1 (Max: Rich)]</p>`,
	},
	885: {
		index: 885,
		text: `<p>To your astonishment, a small bird settles on your shoulder and brightly chirps thrice. Then it flies but a short distance away and chirps again, and you realize that it wants you to follow. You journey by forgotten paths until you come to a tower. From a high window, a maiden with silken hair and eyes like running water calls to you in distress. However, a fierce demon, its four arms each holding a sword as long and wide as a horse, stands guarding the tower.</p>
<p><em>Roll two dice, adding one each for Stealth and Stealing and Weapon Use:</em></p>
<p>❖ 2–7: Though you try, you cannot pass the demon, and with sorrow in your heart, you leave the maiden to her captor. [D-1/S1]</p>
<p>❖ 8+: [Go to paragraph 1389]</p>`,
	},
	886: {
		index: 886,
		text: `<p>As you are walking in leisure, the sky grows dark. Above you passes the greatest flock of birds ever you have seen! Intrigued, you resolve to follow them.</p>
<p><b>No Skill:</b> After many hours, the flock passes from your sight, and you are no wiser to their nature than before. [S1]</p>
<p><b>Determined</b> (mandatory), <b>Wilderness Lore, Seamanship:</b> Long after they have vanished from sight, you still follow them, until after long traveling you come to a tiny island upon which the birds nest as densely as hairs in an old man's beard. Satisfied, you return to where you were. Later, you tell this story to a famous scholar, who marvels at your account and swears to aid you if ever he can assist you. [S1/Scholarship at Master level (I use)]</p>`,
	},
	887: {
		index: 887,
		text: `<p>From a short distance away, you hear an uncanny voice crying, "Free me! Free me!" Hurrying forward, you come across a shadowy djinn hovering over a slain body.</p>
<p><b>No Skill, Sparkling Spear</b> (mandatory): The 'efreet must have killed this man! In a rage, you draw your sword, and with but a blow, you easily slay it—to your great surprise. [D1/S1]</p>
<p><b>Wisdom:</b> Something in the manner of the djinn makes you pause. Seeing you, the 'efreet at once exclaims, "By the will of Allah, free me! This man was a fearsome weaver of enchantments, brought down by his own evil! Take the ring from his finger and destroy it, that I might return to my own lands!" Clearly, this djinn is of the Believing Djinn, and you do as he asks. When the ring is destroyed, he showers you with gratitude, for the joys of the People of the Flame are as great as their wrath. He offers to take you with him as he returns to his home in the Dusky Land. [D1/S1/Opportunity to enter the Dusky Land]</p>`,
	},
	888: {
		index: 888,
		text: `<p>You come across a most wretched and pitiable sight—a creature like unto a wax statue of a man held too close to a flame, and whose legs are transfixed in a pillar of basalt. Its eyes roll in agony, and your heart grows heavy with sympathy.</p>
<p><b>No Skill:</b> However, you have no ability to aid this wretch, and you journey on. [S1]</p>
<p><b>Piety:</b> In a voice of woe, the creature tells how he joined with many other evil 'efreets in a shameful attack on a city of the Faithful. By the wise learnings of a great sorcerer, they were defeated, and he was imprisoned in this form until someone should pray for his release. Moved by pity, you call out to the Merciful and Compassionate God, and the creature is freed! In gratitude, the 'efreet promises to perform a task for you if you ever call his name. [D2/S1/Piety]</p>`,
	},
	889: {
		index: 889,
		text: `<p>As you pass by a well, a strange and terrible voice calls from deep within it, "Oh, please lower a rope!" With great haste and no little fear, you do as the voice asks. When you draw the rope up, clinging to the end is a loathsome demon!</p>
<p><b>No Skill:</b> You scream and bolt in terror, releasing the rope and dropping the creature back to the bottom. You hear his curse clearly as you flee, and know that the creature has set its wrath against you. [D1/<em>Accursed</em>]</p>
<p><b>Determined</b> (mandatory), <b>Enduring Hardship:</b> You do not flinch, but stoically lift the creature from the well. "Thank you," it croaks gratefully. "What boon may I give to my benefactor?" [D1/S1/Choice of W+1 (Max: Princely) or You may lose one status of your choice]</p>`,
	},
	890: {
		index: 890,
		text: `<p>As you journey on your way, you see a most peculiar sight: a great snake, whose flesh is as clear as water and whose scales sparkle like cut diamonds, slithers across your path, pursued by a larger serpent, black and foul of form and scent.</p>
<p><b>No Skill:</b> Fearful, you step back, and both snakes are gone from sight before you can blink. Could you have imagined the whole sight? [S1]</p>
<p><b>Quick Thinking:</b> With a cry, you grab a rock and hurl it at the black snake, crushing its skull. The other snake cries out in a joyful voice and melts into the form of a lustfully beautiful youth. Seizing you, the youngster says, "That vile enchanter stole my form from me and would have slain me had you not interceded! My heart melts in gratitude, and I will love and marry thee if thou desirest."</p>
<p><em>If you are not Married:</em> The sight sets your soul aflame, and you take the other's hand and lead on to a safer place. Praise Allah! [D2/S2/<em>Married</em>]</p>
<p><em>If you are:</em> Though this one's beauty sets your very soul aflame with desire, you think of your spouse who awaits you, and you decline. You lead on to safety, and all who hear of this marvel at your tale. [D2/S2]</p>`,
	},
	891: {
		index: 891,
		text: `<p>As you journey, a voice both clear and strong address you thusly: "I beg your pardon, but could you direct me to civilization?" You turn, and are befuddled to see that the one who addressed you was a horse!</p>
<p><b>No Skill:</b> You calculate the value of this miraculous creature and speak at great length to it, trying to connive some trick by which to lure the beast into following you. Alarmed at the tone of your voice, it runs off. [S1]</p>
<p><b>Beguiling, Golden Bridle:</b> With careful and clever motions, you smoothly win its trust and entice it into a trap. You display this strange beast to all, for a fee, and you turn a fine profit, finally selling the beast to the Sultan for his menagerie. [D1/S1/W+1 (Max: Rich)]</p>`,
	},
	892: {
		index: 892,
		text: `<p>An annoying insect buzzes around your head, and in the sound of its wings you hear a mocking laugh.</p>
<p><b>No Skill:</b> You exhaust yourself trying to squash it. It stings you, then flies off, and you are sure you hear it cackling as it goes. [D1/<em>Diseased</em>]</p>
<p><b>Stealth and Stealing:</b> With a smooth motion, you easily snatch the tiny creature from the air. "Eeeeee!" it squeaks. "Free me and you shall be rich!" You release it, and the strange creature is true to its word. [D1/S2/W+1 (Max: Rich)]</p>`,
	},
	893: {
		index: 893,
		text: `<p>A beautiful snake, with scales like glass, slithers near. You gaze at it in wonder.</p>
<p><b>No Skill:</b> It raises its head and stares back, and a deep tiredness suffuses your limbs. The snake towers above you and takes the form of a beautiful enchantress. You fall to the ground, now wearing the body of the marvelous snake. The mocking laugh of the enchantress fill your head as you slither off. [D1/S1/<em>Beast Form</em>]</p>
<p><b>Appearance:</b> The snake speaks. "Truly, you are so fair and lovely that my heart is filled with joy. I cannot bring harm unto you. I am one versed in the magical arts, and for the solace your visage has brought me, I shall grant any favor you might ask." [D2/S1/Choice of <b>Treasure</b> or Opportunity to enter any Place of Power]</p>`,
	},
	894: {
		index: 894,
		text: `<p>A high-pitched voice greets you by name. Turning, you discover a remarkable thing—a rodent that speaks!</p>
<p><b>No Skill:</b> It offers to grant you a wish. You grab after it, but ho-ho! It flows like water and grows into an enraged 'efreet! "Oh, foolish, greedy mortal," he cries. You turn to run, but are too slow to evade him. A burst of his fury fills your mind... [D1/<em>Ensorcelled</em>]</p>
<p><b>Scholarship, Protective Talisman, Golden Bridle:</b> You greet it in the name of Allah. The beast trembles slightly, and you grow wary. Suspicious, and prudent, you take your leave as the creature calls ineffective curses after you. [D1/Choice of Wisdom or Piety]</p>`,
	},
	895: {
		index: 895,
		text: `<p>You have come across a most horrid beast. You cry out, "By Allah, what a fetid stench, what an aura of evil, accompanies this oddity!" You cannot stay your hand against such a malign presence.</p>
<p><b>No Skill:</b> You charge forward, sword in hand, but the very air around the foul creature is so poisonous that you must flee. Sorely injured, you withdraw. [D1/<em>Wounded</em>]</p>
<p><b>Golden Bridle:</b> You brandish the Golden Bridle, and the creature bows down before you. Holding your nose against the vile vapors it sends forth, you dispatch the foul creature. [D2/S1/Enduring Hardship]</p>`,
	},
	896: {
		index: 896,
		text: `<p>You have cornered a small beast that you discovered gnawing on your belongings. You raise your weapon to deal it a death blow, but are transfixed as it turns its gaze upon you. Your limbs grow weary...</p>
<p><b>No Skill:</b> You are as a statue, having no control over your actions. All that you do, is as the actions of a puppet. When feeling returns to your limbs, you sigh with relief. [D1/<em>Ensorcelled</em> (1 turn)]</p>
<p><b>Luck, Quick Thinking, Golden Bridle:</b> You quickly avert your eyes from its gaze, and the thing scampers off. You do not regret its departure. [D1/S1]</p>`,
	},
	897: {
		index: 897,
		text: `<p>You come across a most beautiful beast, the likes of which you have never before seen. It seems not even slightly dangerous—and what a stunning pelt!</p>
<p><b>No Skill:</b> A beautiful pelt it has, yes, but also sharp teeth, and long and fearsome claws. Fortunately, it seems to be good-natured, for you manage to escape from it with only a handful of wounds. [S1]</p>
<p><b>Wilderness Lore:</b> You observe it for a number of minutes and carefully note its long teeth and claws. Rather than approaching it directly, you set a trap for it. By the grace of Allah, you capture it easily, and its pelt brings a fine price in the bazaar. [D1/S1/W+1 (Max: Rich)]</p>
<p><b>Golden Bridle:</b> When you bring forth the Golden Bridle, it bows down before you and allows you to mount it. It makes a fine steed. Soon after, you sell it to a wealthy man in exchange for many well-fed horses. [D2/S1/W+2 (Max: Rich)]</p>`,
	},
	898: {
		index: 898,
		text: `<p>You have come across a strange beast. Although you approach it with careful steps and making calm sounds, when you draw near, it suddenly charges.</p>
<p><b>No Skill:</b> You flee, but it catches you easily, knocking you to the ground. In terror, you await its terrible jaws... but it merely stands over you for a number of minutes, then moves peaceably away. [D1/S1/Luck]</p>
<p><b>Weapon Use</b> (mandatory): You stand your ground and draw your sword, slashing it across the forequarters. A cut so deep would, you are sure, have felled a lion—but the beast does not yield, and presses its attack with the force of a thunderstorm, relentless and savage... You barely survive the battle. [D1/S1/<em>Wounded</em>]</p>
<p><b>Quick Thinking, Golden Bridle:</b> You drop to the ground, feigning death. Puzzled, the creature nuzzles at you, stands over you for a few minutes, and at last wanders away. [D1/S1/Quick Thinking]</p>`,
	},
	899: {
		index: 899,
		text: `<p>You have come across a most interesting beast, and give it chase. However, it is fleet of foot, and you cannot keep up.</p>
<p><b>No Skill:</b> You follow onward, drawn forward by the faint sounds it makes at it races away from you. Finally, even the sounds disappear. You decide to stop the pursuit. [D1]</p>
<p><b>Wilderness Lore:</b> With craft, you track the creature to its lair. You approach carefully, but as you are about to seize it, it turns and leaps past you. You are stunned by the horror of its visage, and you faint. When you waken, it has disappeared; but where it stood you see a marvelous object. [D1/S1/<em>Insane</em> (1 turn)/<b>Treasure</b>]</p>
<p><b>Golden Bridle:</b> With the power of the Golden Bridle, you easily capture the creature. When you are better able to see it, you faint from its fearsome visage. When you wake, it has disappeared; but where it stood you see a marvelous object. [D1/S1/<b>Treasure</b>]</p>`,
	},
};
